"""Persist the scoped research handoff and audit its exact protocol fields."""
from pathlib import Path
import json, hashlib, datetime, sys
R=Path(__file__).resolve().parents[1]
A=R.parents[1]
AG=A.parent
P=Path('math-open-problems/reports/fei-2026-10-11/EXECUTION_PROTOCOL.json')
def read(p): return Path(p).read_text(encoding='utf-8-sig')
def obj(p): return json.loads(read(p))
def save(p,x): Path(p).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def sha(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()
now=datetime.datetime.now(datetime.timezone.utc).isoformat()
protocol=obj(P)
CF=protocol['required_per_run']['claim_fields']
PF=[x.split(' (')[0] for x in protocol['required_per_run']['progress_fields']]
RF=protocol['required_per_run']['report_fields']
def audit():
    claims=obj(R/'CLAIMS.json'); progress=obj(R/'PROGRESS.json')
    assert set(progress)==set(PF)
    assert progress==obj(R/'PACKET_DELTA.json') and progress['packet_ids']==['A047']
    for c in claims:
        assert set(c)==set(CF)
        assert hashlib.sha256(c['exact_statement'].encode('utf-8')).hexdigest()==c['statement_sha256'],c['claim_id']
    report=read(R/'REPORT.md')
    assert [s[3:] for s in report.splitlines() if s.startswith('## ')]==RF
    assert report.rstrip().split('\n\n')[-1].startswith('Universal bridge:')
    assert len(read(A/'STATUS.md').splitlines())==2
    assert read(A/'STATUS.md').startswith('STATE: ') and read(A/'STATUS.md').splitlines()[1].startswith('NEXT: ')
    files=[p for p in R.rglob('*') if p.is_file() and p.name!='FINAL_AUDIT.json']
    assert all(p.stat().st_size<20_000_000 for p in files)
    result={'status':'PASS','time_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'protocol_revision':protocol['revision'],'claims':len(claims),'progress_keys':len(PF),'report_headings':len(RF),'full_fei':'OPEN','no_formal_check_claimed':True,'files':[{'path':p.relative_to(R).as_posix(),'bytes':p.stat().st_size,'sha256':sha(p)} for p in sorted(files)]}
    save(R/'out/FINAL_AUDIT.json',result)
    print(json.dumps({k:v for k,v in result.items() if k!='files'}))
if '--audit' in sys.argv:
    audit(); raise SystemExit

